    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 51：Skill 5.3.3 インポート鍵と AWS 生成鍵の違い"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"比較項目"}</th><th scope="col"><strong>{"AWS 生成("}<code>{"AWS_KMS"}</code>{")"}</strong></th><th scope="col"><strong>{"インポート("}<code>{"EXTERNAL"}</code>{")"}</strong></th></tr></thead><tbody><tr className={"odd"}><td>{"キーマテリアルの生成"}</td><td><strong>{"KMS の HSM"}</strong></td><td><strong>{"お客様"}</strong></td></tr><tr className={"even"}><td>{"耐久性(Durability)"}</td><td>{"KMS が"}<strong>{"高耐久性"}</strong>{"を管理"}</td><td>{"\n                                    "}<strong>{"お客様が原本を保持する責任"}</strong>{"。KMS\n                                    側の素材が失われた場合は"}<strong>{"再インポート"}</strong>{"で復旧\n                                "}</td></tr><tr className={"odd"}><td>{"有効期限"}</td><td>{"なし"}</td><td><strong>{"設定可能"}</strong>{"(期限切れで素材が削除される)"}</td></tr><tr className={"even"}><td>{"素材だけの削除"}</td><td>{"不可(キー削除は待機期間 7〜30日)"}</td><td>{"\n                                    "}<strong><code>{"DeleteImportedKeyMaterial"}</code>{"\n                                        で即時に使用不能化"}</strong>{"できる\n                                "}</td></tr><tr className={"odd"}><td>{"自動ローテーション"}</td><td><strong>{"可能"}</strong>{"(既定 365日、期間は 90〜2560日で指定)"}</td><td><strong>{"不可"}</strong></td></tr><tr className={"even"}><td>{"オンデマンドローテーション"}</td><td>{"可能"}</td><td><strong>{"可能"}</strong>{"(新素材のインポートが前提)"}</td></tr><tr className={"odd"}><td>{"マルチリージョンキー"}</td><td>{"レプリカへ"}<strong>{"自動で同一素材が複製"}</strong>{"される"}</td><td>{"\n                                    "}<strong>{"各レプリカに同じ素材を手動でインポート"}</strong>{"する必要\n                                "}</td></tr><tr className={"even"}><td>{"運用負荷"}</td><td>{"低い"}</td><td><strong>{"高い"}</strong>{"(生成・保管・再インポート・期限監視)"}</td></tr><tr className={"odd"}><td>{"規制対応の強み"}</td><td>{"一般的な要件"}</td><td><strong>{"鍵生成の主体性、削除の確実性"}</strong>{"を示したい要件"}</td></tr><tr className={"even"}><td>{"暗号文の互換性"}</td><td>{"—"}</td><td>{"\n                                    "}<strong>{"同じ素材でのみ復号可"}</strong>{"(異なる素材を再インポートしても既存暗号文は復号不可)\n                                "}</td></tr></tbody></table>{"\n                "}</div>
