    <h3 id={"skill-534-機密データのマスキング"} tabIndex={-1}>{"Skill 5.3.4 機密データのマスキング"}</h3>
    {"\n                "}
    <h4 id={"ひとことで言うと-9"} tabIndex={-1}>{"ひとことで言うと"}</h4>
    {"\n                "}
    <p>{"\n                    ログやメッセージの中に紛れ込んだ"}<strong>{"個人情報(PII)・認証情報などの機密データを自動で検出し、隠す(マスクする)"}</strong>{"スキルです。「"}<strong>{"そもそも出力しない"}</strong>{"」のが最善ですが、漏れを"}<strong>{"最後の砦で止める"}</strong>{"仕組みを持ちます。\n                "}</p>
    {"\n                "}
    <h4 id={"主な機能"} tabIndex={-1}>{"主な機能"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 52：主な機能"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"サービス/機能"}</th><th scope="col">{"何をするか"}</th><th scope="col">{"動作"}</th></tr></thead><tbody><tr className={"odd"}><td><strong>{"CloudWatch Logs データ保護ポリシー"}</strong></td><td>{"ログに含まれる機密データを"}<strong>{"検出・マスク"}</strong></td><td>{"\n                                    "}<strong>{"マネージドデータ識別子"}</strong>{"(メールアドレス、クレジットカード番号、認証情報など)や"}<strong>{"カスタムデータ識別子"}</strong>{"(正規表現)で検出\n                                "}</td></tr><tr className={"even"}><td><strong>{"Amazon SNS メッセージデータ保護"}</strong></td><td>{"\n                                    トピックを流れるメッセージ内の機密データを"}<strong>{"検出・ブロック・マスク"}</strong>{"\n                                "}</td><td>{"\n                                    "}<strong>{"Audit / Deny / De-identify"}</strong>{" の操作を、"}<strong>{"Inbound(発行)/ Outbound(配信)"}</strong>{"方向で指定\n                                "}</td></tr><tr className={"odd"}><td><strong>{"Amazon Macie"}</strong></td><td>{"\n                                    "}<strong>{"S3 内"}</strong>{"の機密データを"}<strong>{"発見・分類"}</strong>{"\n                                "}</td><td>{"\n                                    機械学習とパターンマッチで PII 等を検出し、"}<strong>{"Security Hub / EventBridge"}</strong>{"\n                                    に通知\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <h4 id={"cloudwatch-logs-データ保護ポリシー"} tabIndex={-1}>{"CloudWatch Logs データ保護ポリシー"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 53：CloudWatch Logs データ保護ポリシー"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"項目"}</th><th scope="col">{"内容"}</th></tr></thead><tbody><tr className={"odd"}><td>{"適用範囲"}</td><td>{"\n                                    "}<strong>{"ロググループ単位"}</strong>{"、または"}<strong>{"アカウント全体"}</strong>{"(アカウントレベルポリシー)\n                                "}</td></tr><tr className={"even"}><td>{"操作"}</td><td>{"\n                                    "}<strong>{"Audit"}</strong>{"(検出して結果を出力)/\n                                    "}<strong>{"Deidentify"}</strong>{"(検出箇所を"}<strong>{"マスク"}</strong>{")\n                                "}</td></tr><tr className={"odd"}><td>{"監査結果の出力先"}</td><td>{"CloudWatch Logs、S3、Firehose"}</td></tr><tr className={"even"}><td>{"マスクされる範囲"}</td><td>{"\n                                    ポリシー適用"}<strong>{"後に取り込まれたログ"}</strong>{"(過去ログには遡らない)\n                                "}</td></tr><tr className={"odd"}><td>{"元の値の閲覧"}</td><td>{"\n                                    "}<strong><code>{"logs:Unmask"}</code></strong>{"\n                                    権限を持つ主体のみ(最小限に付与)\n                                "}</td></tr></tbody></table>{"\n                "}</div>
