    <pre className="code code-block" tabIndex={0} role="group" aria-label="json コード例"><div className="code-line">{"{"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"\"Name\""}</span>{": "}<span className="hljs-string">{"\"sns-data-protection\""}</span>{","}</div><div className="code-line">{"  "}<span className="hljs-attr">{"\"Description\""}</span>{": "}<span className="hljs-string">{"\"カード番号を含むメッセージの発行を拒否する\""}</span>{","}</div><div className="code-line">{"  "}<span className="hljs-attr">{"\"Version\""}</span>{": "}<span className="hljs-string">{"\"2021-06-01\""}</span>{","}</div><div className="code-line">{"  "}<span className="hljs-attr">{"\"Statement\""}</span>{": ["}</div><div className="code-line">{"    {"}</div><div className="code-line">{"      "}<span className="hljs-attr">{"\"DataDirection\""}</span>{": "}<span className="hljs-string">{"\"Inbound\""}</span>{","}</div><div className="code-line">{"      "}<span className="hljs-attr">{"\"Principal\""}</span>{": ["}<span className="hljs-string">{"\"*\""}</span>{"],"}</div><div className="code-line">{"      "}<span className="hljs-attr">{"\"DataIdentifier\""}</span>{": ["}</div><div className="code-line">{"        "}<span className="hljs-string">{"\"arn:aws:dataprotection::aws:data-identifier/CreditCardNumber\""}</span>{""}</div><div className="code-line">{"      ],"}</div><div className="code-line">{"      "}<span className="hljs-attr">{"\"Operation\""}</span>{": { "}<span className="hljs-attr">{"\"Deny\""}</span>{": {} }"}</div><div className="code-line">{"    }"}</div><div className="code-line">{"  ]"}</div><div className="code-line">{"}"}</div></pre>
