    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 54：SNS メッセージデータ保護ポリシー"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"操作"}</th><th scope="col">{"動作"}</th></tr></thead><tbody><tr className={"odd"}><td><strong>{"Audit"}</strong></td><td>{"検出して"}<strong>{"記録"}</strong>{"(通過は許可)"}</td></tr><tr className={"even"}><td><strong>{"Deny"}</strong></td><td>{"検出したら"}<strong>{"メッセージの発行/配信を拒否"}</strong></td></tr><tr className={"odd"}><td><strong>{"De-identify"}</strong></td><td>{"検出箇所を"}<strong>{"マスクまたは削除"}</strong>{"して通過"}</td></tr></tbody></table>{"\n                "}</div>
