    <h4 id={"マスキングの考え方の整理"} tabIndex={-1}>{"「マスキング」の考え方の整理"}</h4>
    {"\n                "}
    <Diagram id="diag-11" label={"「マスキング」の考え方の整理"}/>
    {"\n                "}
    <h4 id={"ベストプラクティス-9"} tabIndex={-1}>{"ベストプラクティス"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 55：ベストプラクティス"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"#"}</th><th scope="col">{"ベストプラクティス"}</th></tr></thead><tbody><tr className={"odd"}><td>{"1"}</td><td>{"\n                                    "}<strong>{"アカウントレベル"}</strong>{"の CloudWatch Logs\n                                    データ保護ポリシーで"}<strong>{"全ロググループに既定適用"}</strong>{"し、設定漏れを防ぐ\n                                "}</td></tr><tr className={"even"}><td>{"2"}</td><td>{"\n                                    まず "}<strong>{"Audit"}</strong>{" で検出状況を把握してから\n                                    "}<strong>{"Deidentify"}</strong>{" を適用(誤検知・影響を確認)\n                                "}</td></tr><tr className={"odd"}><td>{"3"}</td><td>{"\n                                    "}<strong><code>{"logs:Unmask"}</code></strong>{"\n                                    は"}<strong>{"少人数・限定ロール"}</strong>{"にのみ付与し、使用を\n                                    CloudTrail で監査\n                                "}</td></tr><tr className={"even"}><td>{"4"}</td><td>{"\n                                    自社固有の ID\n                                    形式(社員番号など)は"}<strong>{"カスタムデータ識別子"}</strong>{"を定義\n                                "}</td></tr><tr className={"odd"}><td>{"5"}</td><td>{"\n                                    "}<strong>{"S3 の機密データ"}</strong>{"は\n                                    "}<strong>{"Macie"}</strong>{" で定期発見し、結果を\n                                    "}<strong>{"Security Hub"}</strong>{" に集約\n                                "}</td></tr><tr className={"even"}><td>{"6"}</td><td>{"\n                                    "}<strong>{"ログに機密データを出力しないコーディング規約"}</strong>{"を設ける(マスキングは補完策)\n                                "}</td></tr><tr className={"odd"}><td>{"7"}</td><td>{"\n                                    SNS\n                                    は"}<strong>{"トピックごと/既定"}</strong>{"のデータ保護ポリシーで、"}<strong>{"機密を含むメッセージ発行を Deny"}</strong>{"\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <h4 id={"試験のポイント-9"} tabIndex={-1}>{"試験のポイント"}</h4>
    {"\n                "}
    <ul>{"\n                    "}<li>{"\n                        「"}<strong>{"ログ内のメールアドレスやカード番号を自動マスク"}</strong>{"」→\n                        "}<strong>{"CloudWatch Logs データ保護ポリシー(Deidentify)"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"マスクされた値を一部の人だけが見られる"}</strong>{"」→\n                        "}<strong><code>{"logs:Unmask"}</code></strong>{" 権限\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"SNS で機密データを含むメッセージを防ぐ"}</strong>{"」→\n                        "}<strong>{"SNS メッセージデータ保護ポリシー(Deny/De-identify)"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"S3 のどこに機密データがあるか知りたい"}</strong>{"」→\n                        "}<strong>{"Amazon Macie"}</strong>{"(マスキングではなく"}<strong>{"発見・分類"}</strong>{")\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"過去に取り込んだログにもマスクを遡及"}</strong>{"」→\n                        "}<strong>{"遡及しない"}</strong>{"(適用後の取り込み分が対象)\n                    "}</li>{"\n                "}</ul>
    {"\n\n                "}
    <h3 id={"skill-535-鍵と証明書の作成管理"} tabIndex={-1}>{"Skill 5.3.5 鍵と証明書の作成・管理"}</h3>
    {"\n                "}
    <h4 id={"ひとことで言うと-10"} tabIndex={-1}>{"ひとことで言うと"}</h4>
    {"\n                "}
    <p>{"\n                    "}<strong>{"KMS のカスタマーマネージドキー(CMK)"}</strong>{"と\n                    "}<strong>{"TLS 証明書(ACM / AWS Private CA)"}</strong>{"を、"}<strong>{"単一リージョンでも、複数リージョンでも"}</strong>{"、安全に作り・配り・更新・廃棄するスキルです。\n                "}</p>
    {"\n\n                "}
    <h4 id={"part-a-kms-カスタマーマネージドキーの管理"} tabIndex={-1}>{"\n                    Part A: KMS カスタマーマネージドキーの管理\n                "}</h4>
    {"\n                "}
    <p><strong>{"ローテーションの整理(試験頻出)"}</strong></p>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 56：Part A: KMS カスタマーマネージドキーの管理"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"キーの種類"}</th><th scope="col">{"ローテーション"}</th></tr></thead><tbody><tr className={"odd"}><td><strong>{"AWS 所有キー"}</strong></td><td>{"AWS が管理(お客様は関与しない)"}</td></tr><tr className={"even"}><td><strong>{"AWS マネージドキー"}</strong></td><td><strong>{"毎年自動"}</strong>{"(変更・停止不可)"}</td></tr><tr className={"odd"}><td><strong>{"CMK(対称・AWS_KMS)"}</strong></td><td>{"\n                                    "}<strong>{"自動"}</strong>{"(既定\n                                    365日、"}<strong>{"90〜2560日"}</strong>{"でカスタム可)/\n                                    "}<strong>{"オンデマンド"}</strong>{"(最大10回)\n                                "}</td></tr><tr className={"even"}><td><strong>{"CMK(インポート素材)"}</strong></td><td>{"自動不可。"}<strong>{"オンデマンド"}</strong>{"または手動"}</td></tr><tr className={"odd"}><td>{"\n                                    "}<strong>{"CMK(非対称 / HMAC / カスタムキーストア / XKS)"}</strong>{"\n                                "}</td><td>{"\n                                    自動・オンデマンド不可。"}<strong>{"手動"}</strong>{"(新キー作成 +\n                                    "}<strong>{"エイリアス切替"}</strong>{")\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <pre className="code code-block" tabIndex={0} role="group" aria-label="bash コード例"><div className="code-line">{""}<span className="hljs-comment">{"# 自動ローテーションを有効化(180日ごと)"}</span>{""}</div><div className="code-line">{""}<span className="hljs-built_in">{"aws"}</span>{" kms enable-key-rotation \\"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"--key-id"}</span>{" 1234abcd-12ab-34cd-56ef-1234567890ab \\"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"--rotation-period-in-days"}</span>{" "}<span className="hljs-number">{"180"}</span>{""}</div><div className="code-line">{""}</div><div className="code-line">{""}<span className="hljs-comment">{"# 状態確認"}</span>{""}</div><div className="code-line">{""}<span className="hljs-built_in">{"aws"}</span>{" kms get-key-rotation-status \\"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"--key-id"}</span>{" 1234abcd-12ab-34cd-56ef-1234567890ab"}</div><div className="code-line">{""}</div><div className="code-line">{""}<span className="hljs-comment">{"# オンデマンドで今すぐローテーション"}</span>{""}</div><div className="code-line">{""}<span className="hljs-built_in">{"aws"}</span>{" kms rotate-key-on-demand \\"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"--key-id"}</span>{" 1234abcd-12ab-34cd-56ef-1234567890ab"}</div></pre>
    {"\n                "}
    <p>{"\n                    "}<strong>{"ローテーションの重要な性質"}</strong>{" -\n                    "}<strong>{"キー ID / ARN / エイリアスは変わらない"}</strong>{"ので、アプリの変更は不要\n                    -\n                    "}<strong>{"古いキーマテリアルは保持"}</strong>{"され、"}<strong>{"既存の暗号文は引き続き復号できる"}</strong>{"(新規の暗号化は最新素材で実施)\n                    - オンデマンドは"}<strong>{"自動ローテーションのスケジュールを変更しない"}</strong>{"\n                "}</p>
    {"\n                "}
    <p>{"\n                    "}<strong>{"エイリアスの活用(手動ローテーション時)"}</strong>{":\n                    アプリは"}<strong>{"エイリアス"}</strong>{"(例:\n                    "}<code>{"alias/app-data"}</code>{")を指定しておき、新しい KMS\n                    キーを作成したらエイリアスの向き先を付け替えます。ただし、"}<strong>{"古い鍵で暗号化された既存データは古い KMS キーでしか復号できない"}</strong>{"ので、旧キーを"}<strong>{"削除しない"}</strong>{"(または再暗号化する)ことに注意します。\n                "}</p>
    {"\n\n                "}
    <h4 id={"part-b-マルチリージョンキーmulti-region-keys"} tabIndex={-1}>{"\n                    Part B: マルチリージョンキー(Multi-Region Keys)\n                "}</h4>
    {"\n                "}
    <p>{"\n                    "}<strong>{"ひとことで言うと"}</strong>{":\n                    "}<strong>{"異なるリージョンに、同じキー\n                        ID・同じキーマテリアルを持つ「関連キー」"}</strong>{"を作る機能です。"}<strong>{"あるリージョンで暗号化し、別リージョンで(KMS を跨がずに)復号"}</strong>{"できます。\n                "}</p>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 57：Part B: マルチリージョンキー(Multi-Region Keys)"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"項目"}</th><th scope="col">{"内容"}</th></tr></thead><tbody><tr className={"odd"}><td>{"構成"}</td><td>{"\n                                    "}<strong>{"プライマリキー"}</strong>{" 1 つ +\n                                    "}<strong>{"レプリカキー"}</strong>{"(複数リージョン)\n                                "}</td></tr><tr className={"even"}><td>{"キー ID"}</td><td>{"\n                                    "}<strong>{"共通"}</strong>{"(先頭が "}<code>{"mrk-"}</code>{")。ARN\n                                    はリージョンごとに異なる\n                                "}</td></tr><tr className={"odd"}><td>{"共有されるもの"}</td><td>{"\n                                    "}<strong>{"キーマテリアル"}</strong>{"、キー\n                                    ID、Origin、ローテーション設定(プライマリが管理)\n                                "}</td></tr><tr className={"even"}><td><strong>{"共有されない"}</strong>{"もの"}</td><td>{"\n                                    "}<strong>{"キーポリシー"}</strong>{"(リージョンごとに"}<strong>{"独立"}</strong>{")、グラント、エイリアス、タグ\n                                "}</td></tr><tr className={"odd"}><td>{"ユースケース"}</td><td>{"\n                                    "}<strong>{"DR"}</strong>{"、"}<strong>{"DynamoDB グローバルテーブル / Aurora\n                                        グローバルデータベース"}</strong>{"の暗号化、"}<strong>{"クライアント側暗号化"}</strong>{"でリージョン間移動するデータ\n                                "}</td></tr><tr className={"even"}><td>{"注意"}</td><td>{"\n                                    「"}<strong>{"グローバルな1つの鍵"}</strong>{"」ではなく、"}<strong>{"独立したリソースの組"}</strong>{"。"}<strong>{"データ主権要件"}</strong>{"がある場合は、複製先リージョンの妥当性を確認\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <pre className="code code-block" tabIndex={0} role="group" aria-label="bash コード例"><div className="code-line">{""}<span className="hljs-comment">{"# プライマリキーを作成"}</span>{""}</div><div className="code-line">{""}<span className="hljs-built_in">{"aws"}</span>{" kms create-key "}<span className="hljs-attr">{"--multi-region"}</span>{" "}<span className="hljs-attr">{"--description"}</span>{" "}<span className="hljs-string">{"\"mrk primary\""}</span>{" "}<span className="hljs-attr">{"--region"}</span>{" ap-northeast-"}<span className="hljs-number">{"1"}</span>{""}</div><div className="code-line">{""}</div><div className="code-line">{""}<span className="hljs-comment">{"# 別リージョンにレプリカを作成"}</span>{""}</div><div className="code-line">{""}<span className="hljs-built_in">{"aws"}</span>{" kms replicate-key \\"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"--key-id"}</span>{" mrk-1234abcd12ab34cd56ef1234567890ab \\"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"--replica-region"}</span>{" us-west-"}<span className="hljs-number">{"2"}</span>{" \\"}</div><div className="code-line">{"  "}<span className="hljs-attr">{"--region"}</span>{" ap-northeast-"}<span className="hljs-number">{"1"}</span>{""}</div></pre>
    {"\n                "}
    <Diagram id="diag-12" label={"Part B: マルチリージョンキー(Multi-Region Keys)"}/>
    {"\n\n                "}
    <h4 id={"part-c-証明書の管理acm-と-aws-private-ca"} tabIndex={-1}>{"\n                    Part C: 証明書の管理(ACM と AWS Private CA)\n                "}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 58：Part C: 証明書の管理(ACM と AWS Private CA)"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"サービス"}</th><th scope="col">{"役割"}</th><th scope="col">{"用途"}</th></tr></thead><tbody><tr className={"odd"}><td><strong>{"AWS Certificate Manager (ACM)"}</strong></td><td>{"\n                                    "}<strong>{"パブリック/プライベート証明書"}</strong>{"の発行・デプロイ・"}<strong>{"自動更新"}</strong>{"\n                                "}</td><td>{"ALB、CloudFront、API Gateway などの TLS 終端"}</td></tr><tr className={"even"}><td>{"\n                                    "}<strong>{"AWS Private Certificate Authority (Private CA)"}</strong>{"\n                                "}</td><td><strong>{"自社専用の認証局(CA)"}</strong>{"をマネージドで運用"}</td><td>{"\n                                    社内システム、サービス間\n                                    "}<strong>{"mTLS"}</strong>{"、IoT/デバイス証明書、VPN\n                                    クライアント証明書\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <p><strong>{"AWS Private CA の要点"}</strong></p>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 59：Part C: 証明書の管理(ACM と AWS Private CA)"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"項目"}</th><th scope="col">{"内容"}</th></tr></thead><tbody><tr className={"odd"}><td>{"CA 階層"}</td><td>{"\n                                    "}<strong>{"ルート CA + 下位(Subordinate)CA"}</strong>{"\n                                    の階層を構成。"}<strong>{"ルートは使用を最小化"}</strong>{"し、"}<strong>{"下位 CA で発行"}</strong>{"するのが定石\n                                "}</td></tr><tr className={"even"}><td>{"失効管理"}</td><td>{"\n                                    "}<strong>{"CRL"}</strong>{" と\n                                    "}<strong>{"OCSP"}</strong>{" をサポート(失効した証明書を検証側に伝える)\n                                "}</td></tr><tr className={"odd"}><td>{"CA のモード"}</td><td>{"\n                                    "}<strong>{"汎用(General-purpose)"}</strong>{":長めの有効期間 /\n                                    "}<strong>{"短期証明書(Short-lived)"}</strong>{":短い有効期間("}<strong>{"失効管理を不要にする運用向き"}</strong>{"・コストも抑えやすい)\n                                "}</td></tr><tr className={"even"}><td>{"共有"}</td><td>{"\n                                    "}<strong>{"AWS RAM"}</strong>{" で組織内の他アカウントに CA\n                                    を共有し、"}<strong>{"証明書の発行を委任"}</strong>{"\n                                "}</td></tr><tr className={"odd"}><td>{"自動更新"}</td><td>{"\n                                    "}<strong>{"ACM 経由で発行したプライベート証明書は自動更新"}</strong>{"(対応サービスに関連付け時)\n                                "}</td></tr><tr className={"even"}><td>{"範囲"}</td><td>{"\n                                    CA\n                                    は"}<strong>{"リージョン単位"}</strong>{"。マルチリージョン運用では"}<strong>{"リージョンごとの設計"}</strong>{"が必要\n                                "}</td></tr><tr className={"odd"}><td>{"秘密鍵"}</td><td>{"CA の秘密鍵は "}<strong>{"HSM で保護"}</strong></td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <Diagram id="diag-13" label={"Part C: 証明書の管理(ACM と AWS Private CA)"}/>
    {"\n                "}
    <p><strong>{"証明書のリージョン関連の注意"}</strong></p>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 60：Part C: 証明書の管理(ACM と AWS Private CA)"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"項目"}</th><th scope="col">{"内容"}</th></tr></thead><tbody><tr className={"odd"}><td>{"ACM 証明書の範囲"}</td><td>{"\n                                    "}<strong>{"リージョン固有"}</strong>{"。複数リージョンで使うなら"}<strong>{"各リージョンで発行"}</strong>{"\n                                "}</td></tr><tr className={"even"}><td>{"CloudFront"}</td><td>{"使用する証明書は "}<strong>{"us-east-1"}</strong>{" の ACM"}</td></tr><tr className={"odd"}><td>{"期限切れ対策"}</td><td>{"\n                                    "}<strong>{"DNS 検証 + 自動更新"}</strong>{"。"}<strong>{"ACM の期限切れ接近イベント(EventBridge)"}</strong>{"で監視\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n\n                "}
    <h4 id={"ベストプラクティス鍵と証明書"} tabIndex={-1}>{"ベストプラクティス(鍵と証明書)"}</h4>
    {"\n                "}
    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 61：ベストプラクティス(鍵と証明書)"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"#"}</th><th scope="col">{"ベストプラクティス"}</th></tr></thead><tbody><tr className={"odd"}><td>{"1"}</td><td>{"\n                                    "}<strong>{"CMK の自動ローテーションを有効化"}</strong>{"(要件に応じ期間を調整)\n                                "}</td></tr><tr className={"even"}><td>{"2"}</td><td>{"\n                                    "}<strong>{"キーポリシーは最小権限"}</strong>{"。管理者と利用者を分離。"}<code>{"kms:ViaService"}</code>{"、"}<code>{"kms:CallerAccount"}</code>{"、"}<code>{"aws:PrincipalOrgID"}</code>{"\n                                    で"}<strong>{"範囲を限定"}</strong>{"\n                                "}</td></tr><tr className={"odd"}><td>{"3"}</td><td>{"\n                                    "}<strong>{"用途ごとにキーを分ける"}</strong>{"(データ分類・アプリ・環境ごと)ことで、"}<strong>{"影響範囲(ブラストラディウス)"}</strong>{"を限定\n                                "}</td></tr><tr className={"even"}><td>{"4"}</td><td>{"\n                                    アプリは"}<strong>{"エイリアス"}</strong>{"でキーを参照し、ローテーション/切替を容易にする\n                                "}</td></tr><tr className={"odd"}><td>{"5"}</td><td>{"\n                                    "}<strong>{"マルチリージョンキー"}</strong>{"は、DR・グローバルデータの要件がある場合に限定して採用。"}<strong>{"各リージョンのキーポリシーを個別に管理"}</strong>{"\n                                "}</td></tr><tr className={"even"}><td>{"6"}</td><td>{"\n                                    "}<strong>{"削除は慎重に"}</strong>{"。"}<strong>{"無効化 → 一定期間の観察 → 削除予約"}</strong>{"の順で進め、"}<strong>{"削除予約/無効化の検知アラート"}</strong>{"を設定\n                                "}</td></tr><tr className={"odd"}><td>{"7"}</td><td>{"\n                                    証明書は "}<strong>{"ACM で自動更新"}</strong>{"。"}<strong>{"Private CA は階層化"}</strong>{"し、"}<strong>{"ルートは最小利用"}</strong>{"\n                                "}</td></tr><tr className={"even"}><td>{"8"}</td><td><strong>{"短期証明書"}</strong>{"の活用で失効管理の負担を軽減"}</td></tr><tr className={"odd"}><td>{"9"}</td><td>{"\n                                    KMS・ACM・Private CA の操作は\n                                    "}<strong>{"CloudTrail"}</strong>{" で監査し、"}<strong>{"Config ルール"}</strong>{"で準拠を継続検査\n                                "}</td></tr></tbody></table>{"\n                "}</div>
    {"\n                "}
    <h4 id={"試験のポイント-10"} tabIndex={-1}>{"試験のポイント"}</h4>
    {"\n                "}
    <ul>{"\n                    "}<li>{"\n                        「"}<strong>{"ローテーションしてもアプリ変更なし"}</strong>{"」→\n                        "}<strong>{"KMS の自動/オンデマンドローテーション"}</strong>{"(キー ID は不変)\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"非対称キー・HMAC キーをローテーション"}</strong>{"」→\n                        "}<strong>{"手動"}</strong>{"(新キー + エイリアス切替)\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"複数リージョンで同じ鍵で暗号化・復号、KMS 通信を跨ぎたくない"}</strong>{"」→ "}<strong>{"マルチリージョンキー"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"マルチリージョンキーでキーポリシーも自動同期?"}</strong>{"」→\n                        "}<strong>{"同期されない"}</strong>{"(個別管理)\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"社内システム用に自社の認証局を AWS で運用"}</strong>{"」→\n                        "}<strong>{"AWS Private CA"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"複数アカウントで Private CA を共有して証明書を発行"}</strong>{"」→\n                        "}<strong>{"AWS RAM"}</strong>{"\n                    "}</li>{"\n                    "}<li>{"\n                        「"}<strong>{"証明書の自動更新で期限切れを防ぐ"}</strong>{"」→\n                        "}<strong>{"ACM(DNS 検証)"}</strong>{"\n                    "}</li>{"\n                "}</ul>
